function debris(p,x,y,t,r,metal=false){for(let i=0;i<12;i++){const a=i*2.399,d=r*Math.min(1,t*2)*(i%3+1)/3,px=x+Math.cos(a)*d,py=y+Math.sin(a)*d*.45-Math.sin(Math.min(1,t)*pi)*20;p.fillStyle=metal?(i%2?'#d6c291':'#728b90'):(i%2?'#eac17e':'#9d6740');p.save();p.translate(px,py);p.rotate(a+t*4);p.fillRect(-3,-2,6+i%3,4);p.restore();}}
